package com.consense.service.drafting;

import com.consense.common.JsonUtils;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static com.consense.service.drafting.DraftReviewGraph.*;

/** Source reference wire contracts; no model, parser, HTTP or database. */
class DraftDiscoveryReferencesTest {
    private static final String TASK_A="source-long-task-A",TASK_B="source-long-task-B";

    @Test void sharedRepairOwnerSetsUseTaskReferencesAndKeepStableBusinessIds(){
        List<Object> instructions=new ArrayList<>();for(String owner:Arrays.asList(TASK_A,TASK_B))instructions.add(obj("sourceTaskId",owner,"sourceId","one","kind","guidance","sourceObservationId","note-"+owner,"evidenceRefs",Collections.singletonList("one|scope|scope-one"),"scopeObligationIds",Collections.singletonList("scope-one")));
        Map<String,Object> packet=obj("instructions",instructions,"sharedEvidence",Collections.singletonList(obj("sourceId","one","kind","scope","id","scope-one","ref","one|scope|scope-one")));
        Map<String,Object> request=obj("sourceTaskId",TASK_A,"sourceTaskIds",Arrays.asList(TASK_A,TASK_B),"scopeIds",Collections.singletonList("scope-one"),"ruleIds",Collections.singletonList("business_rule"),"missingReferenceInputAliases",Collections.singletonList("twoEnvelopeTendering"));
        DraftDiscoveryReferences refs=DraftDiscoveryReferences.group(packet);JsonNode wire=refs.encode(obj("group",packet,"supplement",obj("repairRequests",Collections.singletonList(request)))).path("supplement").path("repairRequests").path(0);
        assertEquals("t1",wire.path("sourceTaskId").asText());assertEquals(Arrays.asList("t1","t2"),strings(wire.path("sourceTaskIds")));assertEquals("s1",wire.path("scopeIds").path(0).asText());assertEquals("business_rule",wire.path("ruleIds").path(0).asText());assertEquals("twoEnvelopeTendering",wire.path("missingReferenceInputAliases").path(0).asText());
        assertEquals(Arrays.asList(TASK_A,TASK_B),map(request).get("sourceTaskIds"));
    }

    @Test void scopeRulesDecodeSourceReferencesButKeepKnownValueAndRuleAliases(){
        Map<String,Object> rule=obj("id","a1","sourceTaskId","t2","scopeId","s2","when",obj("mode","all","clauses",Collections.singletonList(obj("inputId","k3","operator","eq","value","L10Pro"))),"action","keep","valueSourceId","k4");
        JsonNode raw=JsonUtils.mapper().valueToTree(obj("scopeRules",Collections.singletonList(rule))),decoded=DraftDiscoveryReferences.group(packet()).decode(raw),actual=decoded.path("scopeRules").path(0);
        assertEquals(TASK_B,actual.path("sourceTaskId").asText());assertEquals("scope-shared",actual.path("scopeId").asText());assertEquals("a1",actual.path("id").asText());assertEquals("k3",actual.path("when").path("clauses").path(0).path("inputId").asText());assertEquals("k4",actual.path("valueSourceId").asText());assertEquals("t2",raw.path("scopeRules").path(0).path("sourceTaskId").asText());
    }

    @Test void knownRootOwnerReferencesUseTaskLabelsWithoutChangingRootAliases(){
        Map<String,Object> packet=packet();packet.put("knownRoots",Collections.singletonList(obj("id","k1","sourceTaskIds",Arrays.asList(TASK_A,TASK_B),"questionEn","Keep this question.")));
        String before=JsonUtils.write(packet);DraftDiscoveryReferences refs=DraftDiscoveryReferences.group(packet);JsonNode wire=refs.encode(packet).path("knownRoots").path(0);
        assertEquals("k1",wire.path("id").asText());assertEquals(Arrays.asList("t1","t2"),strings(wire.path("sourceTaskIds")));assertEquals("Keep this question.",wire.path("questionEn").asText());assertEquals(before,JsonUtils.write(packet));
        Map<String,Object> raw=obj("id","k1","sourceTaskId","t2"),branch=obj("id","b1","clauses",Collections.singletonList(obj("inputId","k1","operator","yes")));raw.put("branches",Collections.singletonList(branch));
        JsonNode decoded=refs.decode(JsonUtils.mapper().valueToTree(obj("nodes",Collections.singletonList(raw))));
        assertEquals("k1",decoded.path("nodes").path(0).path("id").asText());assertEquals(TASK_B,decoded.path("nodes").path(0).path("sourceTaskId").asText());assertEquals("k1",decoded.path("nodes").path(0).path("branches").path(0).path("clauses").path(0).path("inputId").asText());
    }

    @Test void initialGroupUsesSmallTypedReferencesWithoutChangingTextOrFixedBusinessKeys(){
        Map<String,Object> packet=packet();String before=JsonUtils.write(packet);DraftDiscoveryReferences refs=DraftDiscoveryReferences.group(packet);JsonNode encoded=refs.encode(packet);
        JsonNode first=encoded.path("instructions").path(0),second=encoded.path("instructions").path(1);
        assertEquals("t1",first.path("sourceTaskId").asText());assertEquals("t2",second.path("sourceTaskId").asText());assertEquals("g1",first.path("sourceObservationId").asText());assertEquals("o1",second.path("sourceObservationId").asText());
        assertEquals(Arrays.asList("s1","c1","g1","r1"),strings(first.path("evidenceRefs")));assertEquals("s1",first.path("scopeObligationIds").path(0).asText());assertEquals("c1",first.path("unresolvedConditionIds").path(0).asText());assertEquals("s1",first.path("currentTemplateAlignment").path("currentEvidenceRefs").path(0).asText());
        assertEquals("s1",encoded.path("sharedEvidence").path(0).path("id").asText());assertEquals("s1",encoded.path("sharedEvidence").path(0).path("ref").asText());assertEquals("g1",encoded.path("sharedEvidence").path(0).path("guidanceNoteId").asText());assertEquals("s2",second.path("scopeObligationIds").path(0).asText());
        assertEquals("Source text literally names source-long-task-A and guidance-A; do not rewrite it.",first.path("text").asText());assertEquals("electronicTendering",encoded.path("fixedContext").path("fields").path(0).path("key").asText());assertEquals("NTT-2-L10PRO",first.path("fixedActionReferences").path(0).path("actionId").asText());assertEquals(before,JsonUtils.write(packet));
        JsonNode receipt=JsonUtils.mapper().valueToTree(refs.receipt());assertEquals("draft-source-references-v1",receipt.path("version").asText());assertTrue(receipt.toString().contains(TASK_A));assertFalse(receipt.toString().contains("Source text literally"));
    }

    @Test void decodingTranslatesOnlySourceFieldsAndUsesTheEffectOwnerForCrossSourceEffects(){
        DraftDiscoveryReferences refs=DraftDiscoveryReferences.group(packet());Map<String,Object> branch=obj("id","g1","scopeId","s1","clauses",Collections.singletonList(obj("inputId","t2","value","g1")));
        Map<String,Object> node=obj("id","s1","sourceTaskId","t1","sourceObservationId","g1","parentId","t1","sourceQuote","t1 s1 guidance-A","branches",Collections.singletonList(branch),"effects",Arrays.asList(obj("scopeId","s1","replacementEn","t1 s2"),obj("sourceTaskId","t2","scopeId","s2","valueSourceId","g1","branchId","s1")));
        Map<String,Object> requirement=obj("id","r1","sourceTaskId","t1","sourceObservationId","c1","nodeIds",Arrays.asList("t2","s1"));JsonNode raw=JsonUtils.mapper().valueToTree(obj("nodes",Collections.singletonList(node),"requirements",Collections.singletonList(requirement),"taskOutcomes",Collections.singletonList(obj("sourceTaskId","t2")),"notes",Collections.singletonList("Do not replace t1 or s1 in prose.")));String before=raw.toString();JsonNode decoded=refs.decode(raw),actual=decoded.path("nodes").path(0);
        assertEquals(TASK_A,actual.path("sourceTaskId").asText());assertEquals("guidance-A",actual.path("sourceObservationId").asText());assertEquals("scope-shared",actual.path("effects").path(0).path("scopeId").asText());assertEquals(TASK_B,actual.path("effects").path(1).path("sourceTaskId").asText());assertEquals("scope-shared",actual.path("effects").path(1).path("scopeId").asText());
        assertEquals("s1",actual.path("id").asText());assertEquals("t1",actual.path("parentId").asText());assertEquals("s1",actual.path("branches").path(0).path("scopeId").asText());assertEquals("t2",actual.path("branches").path(0).path("clauses").path(0).path("inputId").asText());assertEquals("g1",actual.path("effects").path(1).path("valueSourceId").asText());assertEquals("s1",actual.path("effects").path(1).path("branchId").asText());assertEquals("t1 s1 guidance-A",actual.path("sourceQuote").asText());assertEquals("t1 s2",actual.path("effects").path(0).path("replacementEn").asText());assertEquals(Arrays.asList("t2","s1"),strings(decoded.path("requirements").path(0).path("nodeIds")));assertEquals("condition-A",decoded.path("requirements").path(0).path("sourceObservationId").asText());assertEquals(TASK_B,decoded.path("taskOutcomes").path(0).path("sourceTaskId").asText());assertEquals(before,raw.toString());
    }

    @Test void foreignSourceAndWrongNamespaceLabelsCannotBeLaunderedEvenWhenActualIdsCoincide(){
        Map<String,Object> packet=packet();map(list(packet.get("sharedEvidence")).get(0)).put("id","s2");map(list(packet.get("sharedEvidence")).get(0)).put("ref","1|scope|s2");Map<String,Object> first=map(list(packet.get("instructions")).get(0));first.put("evidenceRefs",Arrays.asList("1|scope|s2","1|condition|condition-A","1|guidance|guidance-A","1|relationship|relationship-A"));first.put("scopeObligationIds",Collections.singletonList("s2"));first.remove("currentTemplateAlignment");
        DraftDiscoveryReferences refs=DraftDiscoveryReferences.group(packet);JsonNode decoded=refs.decode(JsonUtils.mapper().valueToTree(obj("nodes",Collections.singletonList(obj("id","n","sourceTaskId","t1","sourceObservationId","o1","effects",Arrays.asList(obj("scopeId","s2"),obj("scopeId","g1")))),"sourceContextRequests",Collections.singletonList(obj("sourceTaskId","t1","kind","member","id","s1")))));
        JsonNode node=decoded.path("nodes").path(0);assertTrue(node.path("sourceObservationId").asText().startsWith("unresolved-source-alias:"));assertNotEquals("s2",node.path("effects").path(0).path("scopeId").asText(),"A foreign alias must not become a coincidentally valid local raw ID");assertTrue(node.path("effects").path(1).path("scopeId").asText().startsWith("unresolved-source-alias:"));assertTrue(decoded.path("sourceContextRequests").path(0).path("id").asText().startsWith("unresolved-source-alias:"));
    }

    @Test void subsequentEvidenceOnlyAppendsAliasesAndRequestsDecodeByDeclaredKind(){
        Map<String,Object> packet=packet();DraftDiscoveryReferences refs=DraftDiscoveryReferences.group(packet);JsonNode first=refs.encode(packet);Map<String,Object> context=obj("sourceId","1","items",Collections.singletonList(obj("kind","member","id","member-current","text","m1 t1 text remains literal","ranges",Collections.singletonList(obj("memberId","member-current","start",0,"end",3)),"adjacentMembers",Collections.singletonList(obj("id","member-next","text","Navigation only")))));
        Map<String,Object> supplement=obj("currentSourceContext",Collections.singletonList(obj("sourceTaskId",TASK_A,"context",context)),"sourceSearchResults",Collections.singletonList(obj("sourceTaskId",TASK_A,"search",obj("sourceId","1","results",Collections.singletonList(obj("kind","scope","id","new-scope","preview","A preview is not full proof","previewOnly",true))))));
        Map<String,Object> prior=obj("nodes",Collections.singletonList(obj("id","s1","sourceTaskId",TASK_A,"sourceObservationId","invented-model-id","effects",Collections.singletonList(obj("scopeId","scope-shared")))));JsonNode follow=refs.encode(obj("group",packet,"priorDraft",prior,"supplement",supplement));JsonNode member=follow.path("supplement").path("currentSourceContext").path(0).path("context").path("items").path(0);
        assertEquals(first.path("instructions"),follow.path("group").path("instructions"));assertEquals("m1",member.path("id").asText());assertEquals("m1",member.path("ranges").path(0).path("memberId").asText());assertEquals("m2",member.path("adjacentMembers").path(0).path("id").asText());assertEquals("m1 t1 text remains literal",member.path("text").asText());assertEquals("s3",follow.path("supplement").path("sourceSearchResults").path(0).path("search").path("results").path(0).path("id").asText());assertEquals("invented-model-id",follow.path("priorDraft").path("nodes").path(0).path("sourceObservationId").asText());assertFalse(JsonUtils.write(refs.receipt()).contains("invented-model-id"));
        JsonNode decoded=refs.decode(JsonUtils.mapper().valueToTree(obj("sourceContextRequests",Arrays.asList(obj("sourceTaskId","t1","kind","member","id","m1"),obj("sourceTaskId","t1","kind","scope","id","s3")),"sourceSearchRequests",Collections.singletonList(obj("sourceTaskId","t2","query","t1 is literal search text")),"baselineContextRequests",Collections.singletonList("electronicTendering"))));
        assertEquals(TASK_A,decoded.path("sourceContextRequests").path(0).path("sourceTaskId").asText());assertEquals("member-current",decoded.path("sourceContextRequests").path(0).path("id").asText());assertEquals("new-scope",decoded.path("sourceContextRequests").path(1).path("id").asText());assertEquals(TASK_B,decoded.path("sourceSearchRequests").path(0).path("sourceTaskId").asText());assertEquals("t1 is literal search text",decoded.path("sourceSearchRequests").path(0).path("query").asText());assertEquals("electronicTendering",decoded.path("baselineContextRequests").path(0).asText());
        JsonNode again=refs.encode(packet);assertEquals(first,again);
    }

    @Test void aRepairSubsetRetainsTheOriginalAliasesAndPriorLocalNodeNamespaces(){
        Map<String,Object> packet=packet();DraftDiscoveryReferences refs=DraftDiscoveryReferences.group(packet);refs.encode(packet);Map<String,Object> subset=obj("instructions",Collections.singletonList(list(packet.get("instructions")).get(1)),"sharedEvidence",Collections.singletonList(list(packet.get("sharedEvidence")).get(4)));
        JsonNode follow=refs.encode(obj("group",subset,"priorDraft",obj("nodes",Collections.singletonList(obj("id","s2","sourceTaskId",TASK_B,"sourceObservationId","marker-B","branches",Collections.singletonList(obj("scopeId","s2","clauses",Collections.singletonList(obj("inputId","t1"))))))),"supplement",obj("repairRequests",Collections.singletonList(obj("sourceTaskId",TASK_B,"scopeIds",Collections.singletonList("scope-shared"))))));
        assertEquals("t2",follow.path("group").path("instructions").path(0).path("sourceTaskId").asText());assertEquals("s2",follow.path("group").path("sharedEvidence").path(0).path("id").asText());assertEquals("t2",follow.path("priorDraft").path("nodes").path(0).path("sourceTaskId").asText());assertEquals("o1",follow.path("priorDraft").path("nodes").path(0).path("sourceObservationId").asText());assertEquals("s2",follow.path("priorDraft").path("nodes").path(0).path("branches").path(0).path("scopeId").asText());assertEquals("t1",follow.path("priorDraft").path("nodes").path(0).path("branches").path(0).path("clauses").path(0).path("inputId").asText());assertEquals("s2",follow.path("supplement").path("repairRequests").path(0).path("scopeIds").path(0).asText());
    }

    @Test void unknownReferencesRemainUnknownAndTaskSourceIdentityCannotBeReassigned(){
        DraftDiscoveryReferences refs=DraftDiscoveryReferences.group(packet());JsonNode raw=JsonUtils.mapper().valueToTree(obj("nodes",Collections.singletonList(obj("id","n","sourceTaskId","missing-task","sourceObservationId","missing-observation","effects",Collections.singletonList(obj("scopeId","missing-scope"))))));assertEquals(raw,refs.decode(raw));
        assertThrows(IllegalArgumentException.class,()->refs.encode(obj("instructions",Collections.singletonList(obj("sourceTaskId",TASK_A,"sourceId","2","sourceObservationId","guidance-A","kind","guidance")))));
    }

    private static List<String> strings(JsonNode values){List<String> result=new ArrayList<>();for(JsonNode value:values)result.add(value.asText());return result;}
    private static Map<String,Object> packet(){
        Map<String,Object> first=obj("sourceTaskId",TASK_A,"sourceId","1","sourceObservationId","guidance-A","kind","guidance","text","Source text literally names source-long-task-A and guidance-A; do not rewrite it.","evidenceRefs",Arrays.asList("1|scope|scope-shared","1|condition|condition-A","1|guidance|guidance-A","1|relationship|relationship-A"),"scopeObligationIds",Collections.singletonList("scope-shared"),"unresolvedConditionIds",Collections.singletonList("condition-A"),"fixedActionReferences",Collections.singletonList(obj("actionId","NTT-2-L10PRO")),"currentTemplateAlignment",obj("sourceTaskId",TASK_A,"currentEvidenceRefs",Collections.singletonList("1|scope|scope-shared"),"currentScopeIds",Collections.singletonList("scope-shared")));
        Map<String,Object> second=obj("sourceTaskId",TASK_B,"sourceId","2","sourceObservationId","marker-B","kind","marker","text","*2.","evidenceRefs",Arrays.asList("2|scope|scope-shared","2|guidance|guidance-B"),"scopeObligationIds",Collections.singletonList("scope-shared"));
        List<Object> evidence=Arrays.asList(obj("ref","1|scope|scope-shared","sourceId","1","kind","scope","id","scope-shared","guidanceNoteId","guidance-A","text","First source scope text."),obj("ref","1|condition|condition-A","sourceId","1","kind","condition","id","condition-A","text","First literal condition."),obj("ref","1|guidance|guidance-A","sourceId","1","kind","guidance","id","guidance-A","text","First guidance."),obj("ref","1|relationship|relationship-A","sourceId","1","kind","relationship","id","relationship-A","parentConditionId","condition-A","childGroupId","scope-shared"),obj("ref","2|scope|scope-shared","sourceId","2","kind","scope","id","scope-shared","text","Second source scope text."),obj("ref","2|guidance|guidance-B","sourceId","2","kind","guidance","id","guidance-B","text","Second guidance."));
        return obj("instructions",Arrays.asList(first,second),"sharedEvidence",evidence,"fixedContext",obj("fields",Collections.singletonList(obj("key","electronicTendering","id","guidance-A","sourceContext",Collections.singletonList(obj("id","scope-shared","text","Historical reference text."))))));
    }
}
